func superviseControllerAdmissionWithAuthority(ctx context.Context, cfg Config, commandName, executable string, authority *rootOCIAuthority) error {
	if commandName != "bootstrap-admit-initial" && commandName != "bootstrap-admit-restart" || executable == "" {
		return errors.New("invalid controller admission child command")
	}
	if authority != nil && (commandName != "bootstrap-admit-restart" || os.Geteuid() != 0) {
		return errors.New("registered admission requires the root restart supervisor")
	}
	// The child digests the exact signed bytes, not a re-encoding.
	wire, err := cfg.signedWire()
	if err != nil || len(wire) == 0 || len(wire) > maxConfigBytes {
		return errors.New("encode bounded controller admission configuration")
	}
	childCtx, cancel := context.WithTimeout(ctx, controllerAdmissionTimeout)
	defer cancel()
	child := exec.CommandContext(childCtx, executable, commandName)
	stdin, err := child.StdinPipe()
	if err != nil {
		return err
	}
	defer stdin.Close()
	child.Stdout = io.Discard
	// Admission errors carry no secret values; keep them in the unit journal.
	child.Stderr = os.Stderr
	child.Env = []string{"PATH=/usr/bin:/bin", "LANG=C"}
	child.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	if commandName == "bootstrap-admit-restart" && os.Geteuid() == 0 {
		uid, gid, err := controllerServiceIdentity()
		if err != nil {
			return err
		}
		child.SysProcAttr.Credential = &syscall.Credential{Uid: uid, Gid: gid, Groups: []uint32{}}
	}
	child.Cancel = func() error {
		if err := syscall.Kill(-child.Process.Pid, syscall.SIGKILL); err != nil {
			if errors.Is(err, syscall.ESRCH) {
				return os.ErrProcessDone
			}
			return err
		}
		return nil
	}
	child.WaitDelay = 5 * time.Second
	if err := child.Start(); err != nil {
		return fmt.Errorf("start controller admission child: %w", err)
	}
	if authority != nil {
		unregister, err := authority.registerAdmissionChild(child.Process.Pid)
		if err != nil {
			cancel()
			_ = child.Wait()
			return fmt.Errorf("register exact controller admission child: %w", err)
		}
		defer unregister()
	}
	if _, err := stdin.Write(wire); err != nil {
		cancel()
		_ = child.Wait()
		return fmt.Errorf("deliver controller admission configuration: %w", err)
	}
	if err := stdin.Close(); err != nil {
		cancel()
		_ = child.Wait()
		return err
	}
	err = child.Wait()
	if ctxErr := childCtx.Err(); ctxErr != nil {
		return fmt.Errorf("controller admission exceeded its startup deadline: %w", ctxErr)
	}
	if err != nil {
		return fmt.Errorf("controller admission child failed: %w", err)
	}
	return nil
}

receipt_verify.text:
func verifyBrokerClaimReply(data []byte, cell, account, raw string, wire []byte, expected, epoch uint64,
	public ed25519.PublicKey, now time.Time) (brokerClaimApplyReply, brokerClaimApplyResponse, error) {
	var reply brokerClaimApplyReply
	if err := json.Unmarshal(data, &reply, json.RejectUnknownMembers(true)); err != nil {
		return reply, brokerClaimApplyResponse{}, fmt.Errorf("decode untrusted broker claim reply: %w", err)
	}
	if reply.Proof == nil {
		return reply, brokerClaimApplyResponse{}, errors.New("unsigned broker claim reply")
	}
	var response brokerClaimApplyResponse
	if err := protocol.DecodeStrict(reply.Proof.Payload, &response, 4096); err != nil {
		return reply, response, err
	}
	if err := protocol.VerifyEnvelope(*reply.Proof, protocol.EnvelopeScope{
		Region: cell, Kind: "broker.claim.receipt", Actor: "broker-controller",
		OperationID: brokerClaimOperationID(raw), Generation: response.Sequence, Epoch: epoch,
	}, public, now, protocol.VerifyPolicy{MaxLifetime: time.Minute, ClockSkew: 30 * time.Second}); err != nil {
		return reply, response, err
	}
	digest := sha256.Sum256([]byte(raw))
	requestDigest := sha256.Sum256(wire)
	if response.Cell != cell || response.Account != account ||
		response.RequestHash != hex.EncodeToString(requestDigest[:]) || response.ExpectedSequence != expected ||
		response.Sequence == 0 || response.Hash != hex.EncodeToString(digest[:]) ||
		response.Status != "fenced" && response.Status != "pending" ||
		response.Status == "fenced" && len(response.Pending) != 0 ||
		response.Status == "pending" && len(response.Pending) == 0 {
		return reply, response, errors.New("signed broker claim receipt does not match the request")
	}
	return reply, response, nil
}

envelope.text:
func VerifyEnvelope(
	envelope Envelope,
	expected EnvelopeScope,
	publicKey ed25519.PublicKey,
	now time.Time,
	policy VerifyPolicy,
) error {
	if len(publicKey) != ed25519.PublicKeySize || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 || !validProtocolTime(now) {
		return ErrInvalidPolicy
	}
	if envelope.SchemaVersion != EnvelopeSchemaVersion {
		return fmt.Errorf("%w: unsupported schema version", ErrInvalidEnvelope)
	}
	actualScope, err := normalizeScope(EnvelopeScope{
		Region: envelope.Region, Kind: envelope.Kind, Actor: envelope.Actor,
		OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	})
	if err != nil {
		return err
	}
	expectedScope, err := normalizeScope(expected)
	if err != nil {
		return err
	}
	if actualScope != expectedScope {
		return ErrScopeMismatch
	}
	if !validProtocolTime(envelope.IssuedAt) || !validProtocolTime(envelope.ExpiresAt) ||
		!envelope.ExpiresAt.After(envelope.IssuedAt) ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > policy.MaxLifetime {
		return fmt.Errorf("%w: invalid timestamp interval", ErrInvalidEnvelope)
	}
	issuedAt := envelope.IssuedAt.Round(0).UTC()
	expiresAt := envelope.ExpiresAt.Round(0).UTC()
	if issuedAt.Sub(now) > policy.ClockSkew {
		return ErrNotYetValid
	}
	if !now.Before(expiresAt) {
		return ErrExpired
	}
	expectedKeyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if envelope.KeyID != expectedKeyID {
		return ErrKeyMismatch
	}
	compact, err := compactPayload(envelope.Payload)
	if err != nil {
		return err
	}
	envelope.Region = actualScope.Region
	envelope.Kind = actualScope.Kind
	envelope.Actor = actualScope.Actor
	envelope.OperationID = actualScope.OperationID
	envelope.IssuedAt = issuedAt
	envelope.ExpiresAt = expiresAt
	envelope.Payload = compact
	material, err := signedMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := base64.RawURLEncoding.DecodeString(envelope.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

operator_claim.text:
func operatorBrokerClaimApply(ctx context.Context, cfg Config, runtime *natscell.Runtime, path, expectedText string, output io.Writer) error {
	if err := natscell.ValidateBrokerOperatorCredentials(cfg.NATS.CredentialsFile, cfg.NATS.Cell); err != nil {
		return err
	}
	if cfg.Operator.BrokerTicketPublicKeyFile == "" {
		return errors.New("broker claim apply requires a pinned ticket public key")
	}
	publicRaw, err := os.ReadFile(cfg.Operator.BrokerTicketPublicKeyFile)
	if err != nil {
		return fmt.Errorf("read pinned broker ticket public key: %w", err)
	}
	public, err := decodePublicKey(string(publicRaw))
	if err != nil {
		return fmt.Errorf("decode pinned broker ticket public key: %w", err)
	}
	expected, err := strconv.ParseUint(expectedText, 10, 64)
	if err != nil {
		return fmt.Errorf("invalid broker claim expected sequence: %w", err)
	}
	info, err := os.Stat(path)
	if err != nil || info.Size() > 64<<10 {
		return errors.New("broker account JWT file is unavailable or too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("read broker account JWT: %w", err)
	}
	raw := strings.TrimSpace(string(data))
	decoded, err := jwt.DecodeAccountClaims(raw)
	if err != nil {
		return err
	}
	if _, err := brokerauth.DecodeAccountJWT(raw, decoded.Subject); err != nil {
		return err
	}
	policy, err := buildSignerPolicy(cfg)
	if err != nil {
		return err
	}
	grant, exists := policy.grant(cfg.Operator.Actor)
	if !exists || !grant.CanRotateBrokerAccount {
		return errors.New("operator is not authorized to rotate the broker account")
	}
	codec, err := policy.withOperator(cfg.Operator)
	if err != nil {
		return err
	}
	snapshot, err := authority.Observe(ctx, runtime.JetStream(), cfg.NATS.Cell)
	if err != nil {
		return err
	}
	if !snapshot.Ready || snapshot.Reason != "observed" || snapshot.Epoch == 0 || !time.Now().Before(snapshot.ExpiresAt) {
		return errors.New("regional authority lease is not current")
	}
	request := brokerClaimApply{Cell: cfg.NATS.Cell, Account: decoded.Subject, JWT: raw, ExpectedSequence: expected}
	payload, err := json.Marshal(request)
	if err != nil {
		return err
	}
	now := time.Now().UTC()
	envelope, err := protocol.SignEnvelope(payload, protocol.EnvelopeScope{
		Region: cfg.NATS.Cell, Kind: "broker.claim.apply", Actor: cfg.Operator.Actor,
		OperationID: brokerClaimOperationID(raw), Generation: expected, Epoch: snapshot.Epoch,
	}, now, now.Add(time.Minute), codec.PrivateKey)
	if err != nil {
		return err
	}
	wire, err := protocol.EncodeJSON(envelope)
	if err != nil {
		return err
	}
	active := runtime
	for attempt := range 3 {
		requestCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
		message, requestErr := active.Conn().RequestWithContext(requestCtx, brokerClaimApplySubject(cfg.NATS.Cell), wire)
		cancel()
		if requestErr == nil {
			var reply brokerClaimApplyReply
			var response brokerClaimApplyResponse
			reply, response, requestErr = verifyBrokerClaimReply(message.Data, cfg.NATS.Cell, decoded.Subject, raw, wire,
				expected, snapshot.Epoch, public, time.Now().UTC())
			if requestErr == nil {
				store, err := brokerauth.OpenStore(ctx, active.JetStream(), cfg.NATS.Cell, nil)
				if err == nil {
					var current brokerauth.Claim
					current, err = store.Read(ctx, decoded.Subject)
					if err == nil && (current.Sequence != response.Sequence || current.Hash != response.Hash || current.JWT != raw) {
						err = errors.New("durable claim differs from signed receipt")
					}
				}
				if err == nil {
					var lease authority.Snapshot
					lease, err = authority.Observe(ctx, active.JetStream(), cfg.NATS.Cell)
					if err == nil && (!lease.Ready || lease.DeploymentID != snapshot.DeploymentID || lease.Epoch != reply.Proof.Epoch || !time.Now().Before(lease.ExpiresAt)) {
						err = errors.New("regional authority changed after the signed broker receipt")
					}
				}
				if err == nil {
					if err := printJSON(output, response); err != nil {
						return err
					}
					if response.Status == "pending" {
						return ErrBrokerFencePending
					}
					return nil
				}
				requestErr = err
			}
		}
		if attempt == 2 || ctx.Err() != nil {
			digest := sha256.Sum256([]byte(raw))
			return fmt.Errorf("broker claim outcome unknown (jwt_sha256=%x expected_sequence=%d): %w", digest, expected, requestErr)
		}
		// Fencing the broker may sever the requester's socket. A new
		// connection retries the same signed, idempotent request; only a
		// fresh acknowledgement can establish completed fencing.
		if active != runtime {
			_ = active.Close()
		}
		connection := cfg.NATS
		connection.ClientRole = "operator"
		connection, err = externalNATS(connection)
		if err != nil {
			digest := sha256.Sum256([]byte(raw))
			return fmt.Errorf("broker claim outcome unknown (jwt_sha256=%x expected_sequence=%d): %w", digest, expected, err)
		}
		active, err = natscell.Start(ctx, connection)
		if err != nil {
			digest := sha256.Sum256([]byte(raw))
			return fmt.Errorf("broker claim outcome unknown (jwt_sha256=%x expected_sequence=%d); reconnect: %w", digest, expected, err)
		}
		defer active.Close()
	}
	return errors.New("broker claim outcome unknown")
}

claim_admission.text:
func serveBrokerClaimAdmission(ctx context.Context, conn *nats.Conn, cell string, policy signerPolicy, gate *brokerGate) (*nats.Subscription, error) {
	return conn.Subscribe(brokerClaimApplySubject(cell), func(message *nats.Msg) {
		if message.Reply == "" || len(message.Data) == 0 || len(message.Data) > maxBrokerClaimWireBytes ||
			gate == nil || !gate.control.Current().CanMutate() {
			return
		}
		requestCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
		defer cancel()
		response, err := verifyAndApplyBrokerClaim(requestCtx, message.Data, cell, policy, gate)
		if errors.Is(err, authority.ErrFenced) || errors.Is(err, authority.ErrNotLeader) || !gate.control.Current().CanMutate() {
			return
		}
		if err != nil {
			wire, marshalErr := json.Marshal(brokerClaimApplyReply{Error: err.Error()})
			if marshalErr == nil {
				_ = message.Respond(wire)
			}
			return
		}
		var envelope protocol.Envelope
		if decodeErr := protocol.DecodeStrict(message.Data, &envelope, maxBrokerClaimWireBytes); decodeErr != nil {
			return
		}
		if err := gate.control.Guard(requestCtx, envelope.Epoch); err != nil {
			return
		}
		local := gate.control.Current()
		observed, err := authority.Observe(requestCtx, gate.runtime.JetStream(), cell)
		if err != nil || !observed.Ready || observed.DeploymentID != gate.deploymentID || local.DeploymentID != gate.deploymentID || observed.Epoch != envelope.Epoch ||
			observed.CandidateID != local.CandidateID || observed.OwnerID != local.OwnerID ||
			!time.Now().Before(observed.ExpiresAt) {
			return
		}
		current, err := gate.store.Read(requestCtx, gate.account)
		if err != nil || current.Sequence != response.Sequence || current.Hash != response.Hash {
			return
		}
		payload, marshalErr := json.Marshal(response)
		if marshalErr != nil {
			return
		}
		if err := gate.control.Guard(requestCtx, envelope.Epoch); err != nil {
			return
		}
		now := time.Now().UTC()
		expires := now.Add(time.Minute)
		if observed.ExpiresAt.Before(expires) {
			expires = observed.ExpiresAt
		}
		if !expires.After(now) {
			return
		}
		proof, signErr := protocol.SignEnvelope(payload, protocol.EnvelopeScope{
			Region: cell, Kind: "broker.claim.receipt", Actor: "broker-controller",
			OperationID: envelope.OperationID, Generation: response.Sequence, Epoch: envelope.Epoch,
		}, now, expires, gate.issuer.Key)
		if signErr != nil {
			return
		}
		wire, marshalErr := json.Marshal(brokerClaimApplyReply{Proof: &proof})
		if marshalErr == nil {
			_ = message.Respond(wire)
		}
	})
}

gate.text:
func startBrokerGate(ctx context.Context, cfg Config, runtime *natscell.Runtime,
	control *authority.Runtime, deploymentID, candidateID string, private ed25519.PrivateKey,
	public ed25519.PublicKey, clock brokerauth.ClockProbe) (*brokerGate, error) {
	if runtime.Bridge() == nil || clock == nil || len(private) != ed25519.PrivateKeySize || len(public) != ed25519.PublicKeySize || !entityid.Valid(deploymentID) {
		return nil, errors.New("production broker gate prerequisites are unavailable")
	}
	if err := natscell.ValidateBrokerControllerCredentials(cfg.NATS.CredentialsFile, cfg.NATS.Cell, cfg.NATS.Instance); err != nil {
		return nil, err
	}
	store, err := brokerauth.OpenStore(ctx, runtime.JetStream(), cfg.NATS.Cell, control)
	if err != nil {
		return nil, err
	}
	allowed := make(map[string]struct{}, len(cfg.NATS.Embedded.BrokerIDs))
	for _, broker := range cfg.NATS.Embedded.BrokerIDs {
		allowed[broker] = struct{}{}
	}
	gate := &brokerGate{runtime: runtime, store: store, control: control, public: public, clock: clock,
		deploymentID: deploymentID,
		cell:         cfg.NATS.Cell, broker: cfg.NATS.Instance, account: runtime.CellAccount(), initialJWT: runtime.InitialCellJWT(),
		brokers: append([]string(nil), cfg.NATS.Embedded.BrokerIDs...)}
	gate.issuer = &brokerauth.Issuer{Store: store, Account: gate.account, Brokers: allowed, Key: private, Clock: clock}
	subject := brokerRPCSubject(gate.cell, "ticket", candidateID)
	subscription, err := runtime.Conn().Subscribe(subject, func(message *nats.Msg) {
		if len(message.Data) == 0 || len(message.Data) > brokerTicketRequestMaxBytes || message.Reply == "" {
			return
		}
		var request brokerauth.TicketRequest
		if json.Unmarshal(message.Data, &request, json.RejectUnknownMembers(true)) != nil {
			return
		}
		requestCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
		defer cancel()
		signed, err := gate.issuer.Issue(requestCtx, request)
		if err != nil {
			return
		}
		wire, err := json.Marshal(signed)
		if err == nil {
			_ = message.Respond(wire)
		}
	})
	if err != nil {
		return nil, fmt.Errorf("serve broker ticket requests: %w", err)
	}
	fenceSubject := brokerRPCSubject(gate.cell, "fence", gate.broker)
	fenceSubscription, err := runtime.Conn().Subscribe(fenceSubject, func(message *nats.Msg) {
		if message.Reply == "" || len(message.Data) == 0 || len(message.Data) > brokerTicketRequestMaxBytes {
			return
		}
		var request fenceRequest
		if json.Unmarshal(message.Data, &request, json.RejectUnknownMembers(true)) != nil {
			return
		}
		requestCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
		defer cancel()
		ack, err := gate.fenceClaim(requestCtx, request)
		if err != nil {
			return
		}
		wire, err := json.Marshal(ack)
		if err == nil {
			_ = message.Respond(wire)
		}
	})
	if err != nil {
		_ = subscription.Unsubscribe()
		return nil, fmt.Errorf("serve broker claim fences: %w", err)
	}
	go func() {
		defer subscription.Unsubscribe()
		defer fenceSubscription.Unsubscribe()
		defer runtime.Bridge().Fence()
		ticker := time.NewTicker(3 * time.Second)
		defer ticker.Stop()
		lastError := ""
		for {
			ctx := observability.StartTrace(ctx)
			if err := gate.renew(ctx); err != nil {
				runtime.Bridge().Fence()
				cause := err.Error()
				if cause != lastError {
					slog.WarnContext(ctx, "regional broker gate closed", "cause", cause)
					lastError = cause
				}
			} else if lastError != "" {
				slog.InfoContext(ctx, "regional broker gate renewed")
				lastError = ""
			}
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
			}
		}
	}()
	return gate, nil
}

renew.text:
func (g *brokerGate) renew(ctx context.Context) error {
	g.mu.Lock()
	defer g.mu.Unlock()
	if _, err := g.clock.Measure(); err != nil {
		return err
	}
	lease, err := authority.Observe(ctx, g.runtime.JetStream(), g.cell)
	if err != nil || !lease.Ready || lease.DeploymentID != g.deploymentID || lease.CandidateID == "" {
		return authority.ErrNotLeader
	}
	claim, err := g.store.Read(ctx, g.account)
	if errors.Is(err, brokerauth.ErrNoClaim) && g.control.Current().CanMutate() {
		claim, err = g.store.Commit(ctx, g.control.Current().Epoch, g.account, g.initialJWT, 0)
	}
	if err != nil {
		return err
	}
	if claim.Sequence != g.applied {
		if err := g.runtime.ApplyCellClaim(ctx, claim.Sequence, claim.JWT); err != nil {
			return err
		}
		g.applied = claim.Sequence
	}
	request, err := brokerauth.NewRequest(g.cell, g.broker, g.account)
	if err != nil {
		return err
	}
	wire, err := json.Marshal(request)
	if err != nil {
		return err
	}
	requestCtx, cancel := context.WithTimeout(ctx, brokerauth.MaxTicketRoundTrip)
	defer cancel()
	started := time.Now()
	reply, err := g.runtime.Conn().RequestWithContext(requestCtx,
		brokerRPCSubject(g.cell, "ticket", lease.CandidateID), wire)
	finished := time.Now()
	if err != nil {
		return err
	}
	if len(reply.Data) == 0 || len(reply.Data) > brokerauth.MaxTicketWireBytes {
		return errors.New("broker ticket reply is too large")
	}
	var signed brokerauth.SignedTicket
	if err := json.Unmarshal(reply.Data, &signed, json.RejectUnknownMembers(true)); err != nil {
		return err
	}
	current, err := g.store.Read(ctx, g.account)
	if err != nil {
		return err
	}
	lease, err = authority.Observe(ctx, g.runtime.JetStream(), g.cell)
	if err != nil {
		return err
	}
	if lease.DeploymentID != g.deploymentID {
		return authority.ErrFenced
	}
	bound, err := g.clock.Measure()
	if err != nil {
		return err
	}
	_, deadline, err := brokerauth.VerifyTicket(signed, g.public, request, started, finished, bound, current, lease)
	if err != nil {
		return err
	}
	if current.Sequence != g.applied {
		return brokerauth.ErrClaimChanged
	}
	return g.runtime.Bridge().OpenUntil(current.Sequence, current.JWT, deadline)
}

fence.text:
func (g *brokerGate) commitAndFence(ctx context.Context, raw string, expectedSequence uint64) (fenceResult, error) {
	result := fenceResult{Acks: make(map[string]fenceAck)}
	if g == nil {
		return result, authority.ErrNotLeader
	}
	if current := g.control.Current(); !current.CanMutate() || current.DeploymentID != g.deploymentID {
		return result, authority.ErrFenced
	}
	g.commitMu.Lock()
	defer g.commitMu.Unlock()
	g.mu.Lock()
	prior, err := g.store.Read(ctx, g.account)
	if errors.Is(err, brokerauth.ErrNoClaim) {
		err = nil
	}
	if err != nil {
		g.mu.Unlock()
		return result, err
	}
	if prior.Sequence != expectedSequence && prior.JWT != raw {
		g.mu.Unlock()
		return result, authority.ErrConflict
	}
	if prior.JWT != raw {
		g.runtime.Bridge().Fence()
	}
	epoch := g.control.Current().Epoch
	claim, err := g.store.Commit(ctx, epoch, g.account, raw, expectedSequence)
	g.mu.Unlock()
	if err != nil {
		return result, err
	}
	result.Claim = claim
	if g.ackedSequence == claim.Sequence && g.ackedHash == claim.Hash {
		for broker, ack := range g.acked {
			result.Acks[broker] = ack
		}
	} else {
		g.ackedSequence, g.ackedHash = claim.Sequence, claim.Hash
		g.acked = make(map[string]fenceAck)
	}
	request := fenceRequest{Cell: g.cell, Account: g.account, Sequence: claim.Sequence, Hash: claim.Hash}
	wire, err := json.Marshal(request)
	if err != nil {
		return result, err
	}
	for _, broker := range g.brokers {
		if _, ok := result.Acks[broker]; ok {
			continue
		}
		var ack fenceAck
		if broker == g.broker {
			ack, err = g.fenceClaim(ctx, request)
		} else {
			requestCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
			var reply *nats.Msg
			reply, err = g.runtime.Conn().RequestWithContext(requestCtx,
				brokerRPCSubject(g.cell, "fence", broker), wire)
			cancel()
			if err == nil && len(reply.Data) <= brokerTicketRequestMaxBytes {
				err = json.Unmarshal(reply.Data, &ack, json.RejectUnknownMembers(true))
			} else if err == nil {
				err = errors.New("broker fence acknowledgement is too large")
			}
		}
		if err != nil || ack.Broker != broker || ack.Cell != g.cell || ack.Account != g.account ||
			ack.Sequence != claim.Sequence || ack.Hash != claim.Hash {
			result.Pending = append(result.Pending, broker)
			continue
		}
		result.Acks[broker] = ack
		g.acked[broker] = ack
	}
	if len(result.Pending) > 0 {
		return result, ErrBrokerFencePending
	}
	return result, nil
}

fence_claim.text:
func (g *brokerGate) fenceClaim(ctx context.Context, request fenceRequest) (fenceAck, error) {
	g.mu.Lock()
	defer g.mu.Unlock()
	if request.Cell != g.cell || request.Account != g.account || request.Sequence == 0 || request.Hash == "" {
		return fenceAck{}, errors.New("broker fence target is invalid")
	}
	claim, err := g.store.Read(ctx, g.account)
	if err != nil {
		return fenceAck{}, err
	}
	if claim.Sequence != request.Sequence || claim.Hash != request.Hash {
		return fenceAck{}, brokerauth.ErrClaimChanged
	}
	g.runtime.Bridge().FenceClaim(request.Sequence)
	if err := g.runtime.ApplyCellClaim(ctx, claim.Sequence, claim.JWT); err != nil {
		return fenceAck{}, err
	}
	g.applied = claim.Sequence
	for g.runtime.Bridge().Status().ActiveSessions != 0 {
		if err := ctx.Err(); err != nil {
			return fenceAck{}, err
		}
		time.Sleep(10 * time.Millisecond)
	}
	status := g.runtime.Bridge().Status()
	if status.Open || status.ActiveSessions != 0 {
		return fenceAck{}, errors.New("broker gate did not close its old sessions")
	}
	return fenceAck{Broker: g.broker, Cell: g.cell, Account: g.account,
		Sequence: claim.Sequence, Hash: claim.Hash}, nil
}

claim_read.text:
func (s *Store) Read(ctx context.Context, account string) (Claim, error) {
	if s == nil || s.stream == nil || !nkeys.IsValidPublicAccountKey(account) {
		return Claim{}, ErrNoClaim
	}
	entry, err := s.stream.GetLastMsgForSubject(ctx, claimSubject(s.cell, account))
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return Claim{}, ErrNoClaim
	}
	if err != nil {
		return Claim{}, fmt.Errorf("read current broker claim: %w", err)
	}
	var record claimRecord
	if len(entry.Data) == 0 || len(entry.Data) > maxAccountJWTBytes+4096 ||
		json.Unmarshal(entry.Data, &record, json.RejectUnknownMembers(true)) != nil ||
		record.Version != 1 || record.Cell != s.cell || record.Account != account || record.Epoch == 0 {
		return Claim{}, errors.New("durable broker claim record is invalid")
	}
	decoded, err := DecodeAccountJWT(record.JWT, account)
	if err != nil || decoded.IssuedAt != record.IssuedAt {
		return Claim{}, errors.New("durable broker claim JWT is invalid")
	}
	digest := sha256.Sum256([]byte(record.JWT))
	return Claim{Cell: s.cell, Account: account, JWT: record.JWT,
		Hash: hex.EncodeToString(digest[:]), Sequence: entry.Sequence, Epoch: record.Epoch,
		IssuedAt: record.IssuedAt, Committed: entry.Time}, nil
}

claim_commit.text:
func (s *Store) Commit(ctx context.Context, epoch uint64, account, raw string, expectedSequence uint64) (Claim, error) {
	if s == nil || s.fencer == nil || epoch == 0 {
		return Claim{}, authority.ErrNotLeader
	}
	decoded, err := DecodeAccountJWT(raw, account)
	if err != nil {
		return Claim{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	for range 8 {
		if err := s.fencer.Guard(ctx, epoch); err != nil {
			return Claim{}, err
		}
		snapshot := s.fencer.Current()
		if !snapshot.CanMutate() || snapshot.Scope != s.cell || snapshot.Epoch != epoch {
			return Claim{}, authority.ErrFenced
		}
		prior, err := s.Read(ctx, account)
		if err != nil && !errors.Is(err, ErrNoClaim) {
			return Claim{}, err
		}
		if prior.Sequence != 0 {
			if prior.JWT == raw {
				return prior, nil
			}
		}
		if prior.Sequence != expectedSequence {
			return Claim{}, authority.ErrConflict
		}
		if prior.Sequence != 0 {
			if decoded.IssuedAt <= prior.IssuedAt {
				return Claim{}, errors.New("replacement account JWT issued-at must strictly increase")
			}
		}
		info, err := s.stream.Info(ctx)
		if err != nil {
			return Claim{}, err
		}
		observed, err := authority.Observe(ctx, s.js, s.cell)
		if err != nil || !observed.Ready || observed.DeploymentID != snapshot.DeploymentID || observed.Epoch != epoch ||
			observed.CandidateID != snapshot.CandidateID || observed.OwnerID != snapshot.OwnerID ||
			observed.Revision > info.State.LastSeq {
			return Claim{}, authority.ErrFenced
		}
		record := claimRecord{Version: 1, Cell: s.cell, Account: account, JWT: raw,
			Epoch: epoch, IssuedAt: decoded.IssuedAt}
		data, err := json.Marshal(record)
		if err != nil {
			return Claim{}, err
		}
		message := &nats.Msg{Subject: claimSubject(s.cell, account), Data: data}
		ack, err := s.js.PublishMsg(ctx, message,
			jetstream.WithExpectLastSequence(info.State.LastSeq),
			jetstream.WithExpectLastSequenceForSubject(expectedSequence, message.Subject))
		if err != nil {
			if ctx.Err() != nil {
				return Claim{}, ctx.Err()
			}
			// A competing lease or claim append requires a fresh Guard. No
			// uncertain publish is reported successful without read-back.
			current, readErr := s.Read(ctx, account)
			if readErr == nil && current.Sequence > expectedSequence {
				if bytes.Equal([]byte(current.JWT), []byte(raw)) && current.Epoch == epoch {
					return current, nil
				}
				return Claim{}, authority.ErrConflict
			}
			continue
		}
		current, err := s.Read(ctx, account)
		if err != nil || current.Sequence != ack.Sequence || current.JWT != raw || current.Epoch != epoch {
			return Claim{}, authority.ErrOutcomeUnknown
		}
		return current, nil
	}
	return Claim{}, authority.ErrConflict
}

nats_start.text:
func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

