func newFenceTestWithStore(t *testing.T, kv jetstream.KeyValue) (*releaseFence, *fenceCell, *fenceLB, jetstream.KeyValue, delivery.Intent) {
	t.Helper()
	balancer := &fenceLB{t: t, down: map[string]bool{}, sets: map[string][]lb.Backend{}}
	for _, node := range []string{"ctl-1", "ctl-2", "ctl-3"} {
		balancer.sets["terrabase"] = append(balancer.sets["terrabase"], lb.Backend{IP: fenceAddresses[node], Port: 9465})
		// ctl-1's ts-auth backend is out of rotation already.
		balancer.sets["ts-auth"] = append(balancer.sets["ts-auth"],
			lb.Backend{IP: fenceAddresses[node], Port: 8080}.Fenced(node == "ctl-1", node == "ctl-1"))
	}
	spec := &cellspec.ReleaseFence{LoadBalancerID: "ocid1.loadbalancer.oc1..x",
		BackendSets: []cellspec.FencedSet{{Name: "terrabase", Port: 9465, MinServing: 1}, {Name: "ts-auth", Port: 8080, MinServing: 1}}}
	cell := &fenceCell{t: t, gate: releaseGate(kv), lb: balancer, nodes: []string{"ctl-1", "ctl-2", "ctl-3"}, release: 7, role: "ts-auth",
		broken: map[string]bool{}}
	fence := &releaseFence{kv: kv, hosts: cell, fencer: &fenceLease{},
		spec: func() (*cellspec.ReleaseFence, map[string]string) { return spec, fenceAddresses },
		open: func(context.Context) (lb.API, error) { return balancer, nil },
		sleep: func(ctx context.Context, _ time.Duration) error {
			time.Sleep(time.Millisecond)
			return ctx.Err()
		}}
	return fence, cell, balancer, kv, delivery.Intent{Role: "ts-auth", Generation: 7}
}

fence_cell.text:
func (c *fenceCell) ListHosts(ctx context.Context) ([]host.HostStatus, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	var statuses []host.HostStatus
	for _, node := range c.nodes {
		desired := host.Desired{Node: node, Role: c.role, Generation: c.release << 24}
		granted, err := c.gate(ctx, node, desired)
		if err != nil {
			return nil, err
		}
		report := host.Report{Node: node, Role: c.role, Environment: c.environment, Generation: (c.release - 1) << 24, State: "running",
			ObservedAt: time.Now()}
		if granted {
			if !slices.Contains(c.restarts, node) {
				c.restarts = append(c.restarts, node)
				if c.restarted != nil {
					defer c.restarted(node)
				}
				// A node restarts only while none of its backends serves.
				c.lb.mu.Lock()
				for set, backends := range c.lb.sets {
					for _, backend := range backends {
						if !c.unfenced && backend.IP == fenceAddresses[node] && backend.Serving() {
							c.t.Errorf("%s restarted while its %s backend serves", node, set)
						}
					}
				}
				c.lb.mu.Unlock()
			}
			if c.stalled[node] {
				continue
			}
			report.Generation, report.State = desired.Generation, "running"
			if c.broken[node] {
				report.State = "failed"
			}
		}
		report.Digest = c.digests[releaseOf(report.Generation)]
		statuses = append(statuses, host.HostStatus{Reports: []host.Report{report}})
	}
	return statuses, nil
}

gated_fixture.text:
func gatedFenceTest(t *testing.T, before, after map[string]string) (*releaseFence, *fenceCell, *fenceLB, canaryGate, *[]string) {
	fence, cell, balancer, _, intent := newFenceTest(t)
	spec, _ := fence.spec()
	spec.Canary = &cellspec.Canary{Project: "p"}
	var calls []string
	gate := func(_ context.Context, target canaryTarget) map[string]string {
		cell.mu.Lock()
		restarted := slices.Contains(cell.restarts, target.Node)
		others := len(cell.restarts) > 1
		cell.mu.Unlock()
		if others || target.Canary.Project != "p" || target.Address != fenceAddresses[target.Node] {
			t.Errorf("gated %+v after other nodes restarted (%v)", target, others)
		}
		if restarted {
			// The canary is still out of rotation.
			for _, backend := range balancer.sets["terrabase"] {
				if backend.IP == target.Address && backend.Serving() {
					t.Errorf("gated %s while it serves", target.Node)
				}
			}
			calls = append(calls, target.Node+" after")
			return after
		}
		calls = append(calls, target.Node+" before")
		return before
	}
	if err := fence.prepare(t.Context(), intent); err != nil {
		t.Fatal(err)
	}
	return fence, cell, balancer, gate, &calls
}

release_gate.text:
func releaseGate(kv jetstream.KeyValue) func(context.Context, string, host.Desired) (bool, error) {
	return func(ctx context.Context, node string, desired host.Desired) (bool, error) {
		release := releaseOf(desired.Generation)
		if _, err := kv.Get(ctx, sequencedKey(desired.Role, release)); errors.Is(err, jetstream.ErrKeyNotFound) {
			return true, nil
		} else if err != nil {
			return false, err
		}
		_, err := kv.Get(ctx, permitKey(desired.Role, release, node))
		if errors.Is(err, jetstream.ErrKeyNotFound) {
			return false, nil
		}
		return err == nil, err
	}
}

sequence.text:
func (f *releaseFence) sequence(ctx context.Context, intent delivery.Intent, gate canaryGate) error {
	role, release := intent.Role, intent.Generation
	// Without a fence every recorded backend returns first, whether or not
	// this release was marked.
	if err := f.reconcile(ctx); err != nil {
		return err
	}
	if _, err := f.kv.Get(ctx, sequencedKey(role, release)); errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil
	} else if err != nil {
		return err
	}
	epoch, err := f.leading(ctx)
	if err != nil {
		return err
	}
	spec, addresses := f.spec()
	if spec == nil {
		// The cell dropped its fence: every node of the release restarts
		// at once.
		if err := f.fencer.Guard(ctx, epoch); err != nil {
			return err
		}
		return f.kv.Delete(ctx, sequencedKey(role, release))
	}
	api, err := f.client(ctx)
	if err != nil {
		return err
	}
	// A node fenced by an earlier release and no longer allocated, its
	// replica withdrawn or moved, keeps no backend out of rotation. Without
	// a replica to wait for, its backends return without waiting for their
	// health checks: the load balancer routes nothing to a failing one, and
	// every fence still needs a healthy alternative.
	left, err := f.keys(ctx, fencedKey("*"))
	if err != nil {
		return err
	}
	for _, key := range left {
		node := strings.TrimPrefix(key, fencedKey(""))
		if allocated, err := f.allocated(ctx, role, release, node); err != nil {
			return err
		} else if !allocated {
			if _, err := f.restore(ctx, api, epoch, node, holdRelease, false); err != nil {
				return err
			}
		}
	}
	grace, settle := durationOr(spec.DrainGraceSeconds, defaultFenceGrace), durationOr(spec.SettleSeconds, defaultFenceSettle)
	var canary *canaryRecord
	if gate != nil && spec.Canary != nil {
		if canary, err = f.canary(ctx, role, release); err != nil {
			return err
		}
	}
	// The workload reconciler may move the release's replicas while it
	// rolls, so the allocations are read again after every node: a node it
	// adds is fenced and permitted before the release opens.
	done := map[string]bool{}
	var nodes []string
nodes:
	for {
		node, found, err := f.nextNode(ctx, role, release, done)
		if err != nil {
			return err
		}
		if !found {
			break
		}
		if canary != nil && canary.Node != "" && !canary.Passed && node != canary.Node && !done[canary.Node] {
			// A new leader resumes with the canary, whichever node another
			// fence holds out.
			if allocated, err := f.allocated(ctx, role, release, canary.Node); err != nil {
				return err
			} else if allocated {
				node = canary.Node
			} else {
				*canary = canaryRecord{}
			}
		}
		done[node], nodes = true, append(nodes, node)
		state, err := f.nodeState(ctx, role, release, node)
		if err != nil {
			return err
		}
		target := canaryTarget{Role: role, Node: node, Address: addresses[node], OperationID: intent.OperationID, Generation: intent.Generation}
		if spec.Canary != nil {
			target.Canary = *spec.Canary
		}
		if canary != nil && canary.Node == "" {
			// The first node is the canary. Its baseline is taken before it
			// changes; one that already serves the release has none, so
			// every check must pass.
			canary.Node = node
			if state != "running" {
				baseline := target
				baseline.Baseline = true
				canary.Baseline = slices.Sorted(maps.Keys(gate(ctx, baseline)))
				slog.InfoContext(ctx, "release canary baseline", observability.ComponentKey, "rollout", "role", role,
					"release", release, "node", node, "failing", canary.Baseline)
			}
			if err := f.saveCanary(ctx, epoch, role, release, *canary); err != nil {
				return err
			}
		}
		if state != "running" {
			if err := f.fence(ctx, api, epoch, *spec, node, addresses[node], grace, holdRelease); err != nil {
				return err
			}
			if err := f.fencer.Guard(ctx, epoch); err != nil {
				return err
			}
			if _, err := f.kv.Put(ctx, permitKey(role, release, node), []byte("{}")); err != nil {
				return err
			}
			slog.InfoContext(ctx, "release fence permits a node", observability.ComponentKey, "rollout", "role", role,
				"release", release, "node", node)
			for state != "running" {
				if state == "failed" {
					return fmt.Errorf("%w: %s replica %s failed release %d; its backends stay fenced", errBadRelease, role, node, release)
				}
				if err := f.wait(ctx, epoch, fencePoll); err != nil {
					return fmt.Errorf("%s replica %s did not serve release %d: %w", role, node, release, err)
				}
				if allocated, err := f.allocated(ctx, role, release, node); err != nil {
					return err
				} else if !allocated {
					// The reconciler withdrew the replica: its node's other
					// workloads return to rotation, and the next node may be
					// its replacement.
					slog.InfoContext(ctx, "release fence returns a withdrawn node", observability.ComponentKey, "rollout", "role", role,
						"release", release, "node", node)
					if _, err := f.restore(ctx, api, epoch, node, holdRelease, false); err != nil {
						return err
					}
					if canary != nil && canary.Node == node && !canary.Passed {
						// The next node is the canary.
						*canary = canaryRecord{}
						if err := f.saveCanary(ctx, epoch, role, release, *canary); err != nil {
							return err
						}
					}
					continue nodes
				}
				if state, err = f.nodeState(ctx, role, release, node); err != nil {
					return err
				}
			}
		}
		if canary != nil && canary.Node == node && !canary.Passed {
			// Still out of rotation: the release reaches no other node
			// unless the canary passes.
			if err := f.gateCanary(ctx, epoch, gate, target, release, canary); err != nil {
				return err
			}
		}
		returned, err := f.restore(ctx, api, epoch, node, holdRelease, true)
		if err != nil {
			return err
		}
		if returned {
			if err := f.wait(ctx, epoch, settle); err != nil {
				return err
			}
		}
	}
	keys := []string{sequencedKey(role, release)}
	for _, node := range nodes {
		keys = append(keys, permitKey(role, release, node))
	}
	// The mark goes last, so an interrupted cleanup leaves the release held,
	// never open.
	slices.Reverse(keys)
	for _, key := range keys {
		if err := f.deleteGuarded(ctx, epoch, key); err != nil {
			return err
		}
	}
	return f.sweep(ctx, epoch, role, release)
}

canary_read.text:
func (f *releaseFence) canary(ctx context.Context, role string, release uint64) (*canaryRecord, error) {
	entry, err := f.kv.Get(ctx, sequencedKey(role, release))
	if err != nil {
		return nil, err
	}
	var record canaryRecord
	if err := json.Unmarshal(entry.Value(), &record); err != nil {
		return nil, fmt.Errorf("decode the canary of %s release %d: %w", role, release, err)
	}
	return &record, nil
}

canary_save.text:
func (f *releaseFence) saveCanary(ctx context.Context, epoch uint64, role string, release uint64, record canaryRecord) error {
	wire, err := json.Marshal(record)
	if err != nil {
		return err
	}
	if err := f.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = f.kv.Put(ctx, sequencedKey(role, release), wire)
	return err
}

select.text:
func (h *nativeHistory) selectedCanaryGate(state nativeReleaseHistory, binding nativeReleaseBinding) canaryGate {
	if h.canary == nil {
		return nil
	}
	candidate := cloneNativeProfile(binding.Profile)
	baseline := candidate
	if state.Previous != nil {
		baseline = cloneNativeProfile(state.Previous.Binding.Profile)
	}
	check := h.canary
	return func(ctx context.Context, target canaryTarget) map[string]string {
		target.Profile = candidate
		if target.Baseline {
			target.Profile = baseline
		}
		return check(ctx, target)
	}
}

smoke.text:
func (g smokeGate) check(ctx context.Context, target canaryTarget) map[string]string {
	failed := map[string]string{}
	fail := func(check string, err error) {
		if err != nil {
			failed[check] = err.Error()
		}
	}
	canary := target.Canary
	authURL, apiURL, api := canary.AuthURL, canary.APIURL, g.public
	var memberErr error
	switch target.Role {
	case tsauth.Role:
		authURL = "http://" + net.JoinHostPort(target.Address, strconv.Itoa(cmp.Or(g.authPort, tsauth.Port)))
	case terrabase.Role:
		var memberProfile terrabase.Profile
		memberProfile, memberErr = terrabase.ParseProfile(target.Profile.Env)
		if memberErr == nil && memberProfile.ClientPort == 0 {
			memberErr = errors.New("the selected terrabase profile has no client port")
		}
		if memberErr == nil {
			apiURL = "https://" + net.JoinHostPort(target.Address, strconv.Itoa(memberProfile.ClientPort))
			api, memberErr = g.member(target.Address)
		}
	}
	fail(checkAuthDiscovery, discoverAuth(ctx, g.public, authURL))
	credentials, err := g.credentials(ctx, target)
	if err == nil && !time.Now().Before(credentials.ExpiresAt) {
		err = errors.New("native canary credential delivery expired")
	}
	if err == nil {
		var cancel context.CancelFunc
		ctx, cancel = context.WithDeadline(ctx, credentials.ExpiresAt)
		defer cancel()
	}
	authKey, terraBaseKey, keyErr := canaryKeys(credentials.Value)
	if err == nil {
		err = keyErr
	}
	if err != nil {
		failed[checkAuthToken], failed[checkDocuments] = err.Error(), err.Error()
	} else {
		token, err := g.token(ctx, authURL, authKey)
		fail(checkAuthToken, err)
		switch bearer := cmp.Or(terraBaseKey, token); {
		case bearer == "":
			failed[checkDocuments] = "no TerraBase credential: no tb_ key and no ts-auth token"
		case memberErr != nil:
			failed[checkDocuments] = memberErr.Error()
		default:
			fail(checkDocuments, documentCRUD(ctx, api, apiURL, bearer, canary))
		}
	}
	if canary.DashboardLoginURL != "" {
		fail(checkDashboard, dashboardLogin(ctx, g.public, canary.DashboardLoginURL))
	}
	return failed
}

call.text:
func call(ctx context.Context, client *http.Client, method, target string, header http.Header, body []byte,
) (*http.Response, []byte, error) {
	ctx, cancel := context.WithTimeout(ctx, canaryCheckTimeout)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, method, target, bytes.NewReader(body))
	if err != nil {
		return nil, nil, err
	}
	if header != nil {
		request.Header = header
	}
	response, err := client.Do(request)
	if err != nil {
		return nil, nil, err
	}
	defer response.Body.Close()
	data, err := io.ReadAll(io.LimitReader(response.Body, 1<<20))
	return response, data, err
}

crud.text:
func documentCRUD(ctx context.Context, client *http.Client, apiURL, token string, canary cellspec.Canary) (err error) {
	collections := apiURL + "/v1/projects/" + url.PathEscape(canary.Project) + "/databases/" +
		url.PathEscape(canary.Database) + "/collections"
	send := func(method, target string, extra http.Header, body []byte) (*http.Response, []byte, error) {
		header := http.Header{"Authorization": {"Bearer " + token}}
		if body != nil {
			header.Set("Content-Type", "application/json")
		}
		for name, values := range extra {
			header[name] = values
		}
		return call(ctx, client, method, target, header, body)
	}
	expect := func(step string, status int, response *http.Response, body []byte, err error) error {
		if err != nil {
			return fmt.Errorf("%s: %w", step, err)
		}
		if response.StatusCode != status {
			return unexpected(step, response, body)
		}
		return nil
	}
	// The collection is created on first use; 409 means it exists.
	response, body, err := send(http.MethodPost, collections, nil, []byte(`{"name":"`+canaryCollection+`"}`))
	if err == nil && response.StatusCode == http.StatusConflict {
		response.StatusCode = http.StatusCreated
	}
	if err := expect("create the collection", http.StatusCreated, response, body, err); err != nil {
		return err
	}
	document := collections + "/" + canaryCollection + "/documents/" + entityid.New()
	response, body, err = send(http.MethodPut, document, http.Header{"If-None-Match": {"*"}}, []byte(`{"n":1}`))
	if err := expect("create a document", http.StatusCreated, response, body, err); err != nil {
		return err
	}
	defer func() {
		if err != nil {
			// Best effort: a failed check leaves no document behind.
			_, _, _ = send(http.MethodDelete, document, nil, nil)
		}
	}()
	created := response.Header.Get("ETag")
	response, body, err = send(http.MethodGet, document, nil, nil)
	if err := expect("read the document", http.StatusOK, response, body, err); err != nil {
		return err
	}
	var read struct {
		Document struct {
			N int `json:"n"`
		} `json:"document"`
	}
	if created == "" || response.Header.Get("ETag") != created || json.Unmarshal(body, &read) != nil || read.Document.N != 1 {
		return errors.New("the document read back differs from the one written")
	}
	response, body, err = send(http.MethodPut, document, http.Header{"If-Match": {created}}, []byte(`{"n":2}`))
	if err := expect("replace the document with If-Match", http.StatusOK, response, body, err); err != nil {
		return err
	}
	replaced := response.Header.Get("ETag")
	if replaced == "" || replaced == created {
		return errors.New("the replaced document has no new ETag")
	}
	response, body, err = send(http.MethodPut, document, http.Header{"If-Match": {created}}, []byte(`{"n":3}`))
	if err := expect("replace the document with a stale If-Match", http.StatusPreconditionFailed, response, body, err); err != nil {
		return err
	}
	response, body, err = send(http.MethodDelete, document, http.Header{"If-Match": {replaced}}, nil)
	return expect("delete the document with If-Match", http.StatusOK, response, body, err)
}

keys.text:
func canaryKeys(value string) (authKey, terraBaseKey string, err error) {
	for key := range strings.FieldsSeq(value) {
		switch {
		case strings.HasPrefix(key, "tsk_") && len(key) == len(canaryProbeKey) && key[24] == '_':
			authKey = key
		case strings.HasPrefix(key, "tb_"):
			terraBaseKey = key
		default:
			return "", "", errors.New("the canary credentials hold something other than a tsk_ and a tb_ key")
		}
	}
	return authKey, terraBaseKey, nil
}

member.text:
func (g smokeGate) member(address string) (*http.Client, error) {
	roots := x509.NewCertPool()
	if len(g.memberCA) == 0 || !roots.AppendCertsFromPEM(g.memberCA) {
		return nil, errors.New("this controller has no TerraBase member CA")
	}
	transport := http.DefaultTransport.(*http.Transport).Clone()
	transport.TLSClientConfig = &tls.Config{RootCAs: roots, ServerName: address, MinVersion: tls.VersionTLS12}
	return &http.Client{Transport: transport, CheckRedirect: g.public.CheckRedirect}, nil
}

