func startStatusRecorder(t *testing.T) (*statusRecorder, budget.StatusPage) {
	t.Helper()
	recorder := &statusRecorder{}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		recorder.mu.Lock()
		recorder.requests = append(recorder.requests, r.Method+" "+r.URL.Path)
		recorder.mu.Unlock()
		w.WriteHeader(http.StatusCreated)
		_, _ = io.WriteString(w, `{"id":"`+testWarningID+`","url":"/incidents/x"}`)
	}))
	t.Cleanup(srv.Close)
	return recorder, budget.StatusPage{URL: srv.URL + "/api/operator", HTTP: srv.Client(),
		Token: func(context.Context) (string, error) { return "test-token", nil }}
}

tick.text:
func (a *capacityAllocator) tick(ctx context.Context, now time.Time) error {
	snapshot := a.global.authority.Current()
	if !snapshot.CanMutate() {
		return nil
	}
	rollups := a.regions()
	if len(rollups) == 0 {
		// The region view attaches after the controller starts; there is nothing to allocate yet.
		return nil
	}
	regions := capacityRegions(rollups)
	if roster, _, err := a.global.reader.Roster(ctx); err == nil {
		regions = addRosterCells(regions, roster)
	}
	_, proof, inventory, factsErr := a.reservations.facts(ctx)
	if factsErr == nil {
		if err := a.reservations.reconcile(ctx, snapshot.Epoch, proof, inventory); err != nil {
			slog.Warn("capacity commitments await positive resource observations", observability.ComponentKey, "budget", "error", err)
		}
	}
	capacity, allocationErr := budget.AllocateInfrastructure(ctx, a.global.reader, proof, inventory, regions, nil, now)
	if factsErr != nil {
		capacity.Reason = "infrastructure candidate planning is held: " + factsErr.Error()
	}
	if err := a.global.authority.Guard(ctx, snapshot.Epoch); err != nil {
		return err
	}
	if err := budget.WriteCapacity(ctx, a.global.writer, snapshot.Epoch, capacity); err != nil {
		return fmt.Errorf("write capacity: %w", err)
	}
	a.mu.Lock()
	a.capacity, a.found = capacity, true
	a.mu.Unlock()
	a.journal(ctx, now, snapshot.Epoch, capacity)
	a.alertBudget(ctx, now, snapshot.Epoch, capacity)
	return errors.Join(factsErr, allocationErr)
}

facts.text:
func (r *capacityReservations) facts(ctx context.Context) (*capacityinventory.Reader, region.VerifiedInfrastructureSpend, capacityinventory.Snapshot, error) {
	if r == nil || r.spending == nil {
		return nil, region.VerifiedInfrastructureSpend{}, capacityinventory.Snapshot{}, fmt.Errorf("%w: signed infrastructure spending authority is unavailable", nodescale.ErrCapacityPending)
	}
	proof, err := r.spending.InfrastructureSpend(ctx)
	if err != nil {
		return nil, proof, capacityinventory.Snapshot{}, err
	}
	ociRegion, err := oci.Region(strings.ToUpper(r.cell)).OCIRegion()
	if err != nil {
		return nil, proof, capacityinventory.Snapshot{}, err
	}
	factory, err := instancePrincipal(ctx, ociRegion)
	if err != nil {
		return nil, proof, capacityinventory.Snapshot{}, err
	}
	reader, err := capacityinventory.New(factory)
	if err != nil {
		return nil, proof, capacityinventory.Snapshot{}, err
	}
	snapshot, err := reader.Read(ctx, proof.Footprint())
	if err == nil {
		err = snapshot.Validate(proof.Footprint(), time.Now())
	}
	return reader, proof, snapshot, err
}

alert.text:
func (a *capacityAllocator) alertBudget(ctx context.Context, now time.Time, epoch uint64, capacity budget.Capacity) {
	alert := &a.alert
	if alert.unsaved != nil {
		if err := a.saveAlert(ctx, epoch, *alert.unsaved); err != nil {
			a.alertFailed(ctx, now, epoch, err)
			return
		}
		alert.unsaved = nil
	}
	record, err := alert.load(ctx)
	if err != nil {
		a.alertFailed(ctx, now, epoch, err)
		return
	}
	if budget.Alerting(record.Open, capacity) == record.Open {
		alert.failure, alert.missing = "", false
		return
	}
	if err := a.global.authority.Guard(ctx, epoch); err != nil {
		a.alertFailed(ctx, now, epoch, err)
		return
	}
	next := alertRecord{At: now}
	if record.Open {
		err = alert.status.ResolveWarning(ctx, record.Incident)
	} else {
		next.Open = true
		next.Incident, err = alert.status.OpenWarning(ctx)
	}
	if err != nil {
		a.alertFailed(ctx, now, epoch, err)
		return
	}
	if err := a.saveAlert(ctx, epoch, next); err != nil {
		alert.unsaved = &next
		a.alertFailed(ctx, now, epoch, err)
		return
	}
	alert.failure, alert.missing = "", false
}

alert_load.text:
func (b *budgetAlert) load(ctx context.Context) (alertRecord, error) {
	kv, err := b.bucket(ctx)
	if err != nil {
		return alertRecord{}, err
	}
	entry, err := kv.Get(ctx, alertKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return alertRecord{}, nil
	}
	if err != nil {
		return alertRecord{}, fmt.Errorf("read budget alert: %w", err)
	}
	var record alertRecord
	if err := protocol.DecodeStrict(entry.Value(), &record, maxAlertBytes); err != nil {
		return alertRecord{}, fmt.Errorf("decode budget alert: %w", err)
	}
	return record, nil
}

regions.text:
func capacityRegions(rollups []globalview.Region) []budget.Region {
	regions := make([]budget.Region, 0, len(rollups))
	for _, rollup := range rollups {
		region := budget.Region{Cell: rollup.Cell}
		if rollup.Rollup != nil && rollup.Rollup.Scale != nil {
			scale := rollup.Rollup.Scale
			region = budget.Region{Cell: rollup.Cell, Nodes: scale.Nodes, Want: scale.Want, Pressure: scale.Pressure, At: scale.At}
		}
		regions = append(regions, region)
	}
	return regions
}

roster.text:
func addRosterCells(regions []budget.Region, roster globalcontrol.Roster) []budget.Region {
	known := make(map[string]bool, len(regions))
	for _, region := range regions {
		known[region.Cell] = true
	}
	for _, entry := range roster.Regions {
		if !known[entry.Cell] {
			known[entry.Cell] = true
			regions = append(regions, budget.Region{Cell: entry.Cell})
		}
	}
	return regions
}

budgets.text:
func (budgets capacityBudgets) Budgets(ctx context.Context) ([]insights.Budget, error) {
	capacity, found, err := budgets.latest(ctx)
	if err != nil || !found {
		return nil, err
	}
	switch capacity.State {
	case budget.StateOK, budget.StateWarn, budget.StateOver:
	default:
		return nil, nil
	}
	return []insights.Budget{{Name: "monthly OCI budget", Used: float64(capacity.ProjectedCents) / 100,
		Ceiling: float64(capacity.CapCents) / 100, Unit: capacity.Currency}}, nil
}

latest.text:
func (budgets capacityBudgets) latest(ctx context.Context) (budget.Capacity, bool, error) {
	if budgets.allocator != nil {
		if capacity, found := budgets.allocator.Capacity(); found {
			return capacity, true, nil
		}
	}
	if budgets.global == nil || budgets.global.reader == nil {
		return budget.Capacity{}, false, nil
	}
	return budget.ReadCapacity(ctx, budgets.global.reader)
}

budget_set.text:
func serveBudgetSet(ctx context.Context, conn *nats.Conn, leader budgetLeader, writer *globalcontrol.Writer) error {
	subscription, err := conn.Subscribe(protocol.GlobalBudgetSetSubject(), func(message *nats.Msg) {
		snapshot := leader.Current()
		if !snapshot.CanMutate() {
			return
		}
		requestCtx, cancel := context.WithTimeout(ctx, budgetSetTimeout)
		defer cancel()
		err := applyBudgetSet(requestCtx, leader, writer, snapshot.Epoch, message.Data)
		if errors.Is(err, authority.ErrFenced) || errors.Is(err, authority.ErrNotLeader) {
			return
		}
		response := budgetSetResponse{}
		if err != nil {
			response.Error = err.Error()
		}
		if wire, err := json.Marshal(response); err == nil {
			_ = message.Respond(wire)
		}
	})
	if err != nil {
		return fmt.Errorf("subscribe to budget requests: %w", err)
	}
	go func() {
		<-ctx.Done()
		_ = subscription.Unsubscribe()
	}()
	return nil
}

budget_apply.text:
func applyBudgetSet(ctx context.Context, leader budgetLeader, writer *globalcontrol.Writer, epoch uint64, wire []byte) error {
	var next budget.Budget
	if err := protocol.DecodeStrict(wire, &next, maxBudgetSetBytes); err != nil {
		return fmt.Errorf("decode budget request: %w", err)
	}
	if err := next.Validate(); err != nil {
		return err
	}
	if err := leader.Guard(ctx, epoch); err != nil {
		return err
	}
	if err := budget.WriteBudget(ctx, writer, epoch, next); err != nil {
		return fmt.Errorf("write monthly budget: %w", err)
	}
	decisionlog.Record(ctx, decisionlog.Decision{Time: time.Now(), Region: "global", Epoch: epoch,
		Actor: decisionlog.Actor{Slice: "budget"}, Kind: decisionlog.KindHoldCleared,
		Subject: decisionlog.Subject{Kind: "budget", ID: "monthly"},
		Summary: "set the monthly budget to " + budget.Money(next.MonthlyCapCents, next.Currency),
		Reason:  "set by " + next.SetBy})
	return nil
}

set.text:
func (page *capacityPage) SetBudget(ctx context.Context, next budget.Budget) error {
	if page.global.writer == nil {
		return dashboard.ErrBudgetNotHome
	}
	wire, err := protocol.EncodeJSON(next)
	if err != nil {
		return err
	}
	reply, err := page.conn.RequestWithContext(ctx, protocol.GlobalBudgetSetSubject(), wire)
	if err != nil {
		return fmt.Errorf("ask the global leader: %w", err)
	}
	var response budgetSetResponse
	if err := protocol.DecodeStrict(reply.Data, &response, maxBudgetSetBytes); err != nil {
		return fmt.Errorf("read the global leader's answer: %w", err)
	}
	if response.Error != "" {
		return errors.New(response.Error)
	}
	return nil
}

page.text:
func (page *capacityPage) Capacity(ctx context.Context) dashboard.CapacityView {
	data := dashboard.CapacityView{Home: page.global.writer != nil}
	if next, found, err := budget.ReadBudget(ctx, page.global.reader); err != nil {
		data.Unavailable = append(data.Unavailable, "monthly budget")
	} else if found {
		data.Budget = &next
	}
	if capacity, found, err := budget.ReadCapacity(ctx, page.global.reader); err != nil {
		data.Unavailable = append(data.Unavailable, "capacity document")
	} else if found {
		data.Capacity = &capacity
	}
	if page.scale != nil {
		data.Scale = page.scale()
	}
	if store := page.suggestions.Load(); data.Home && store != nil {
		suggestion, found, err := store.Suggestion(ctx)
		switch {
		case err != nil:
			data.Unavailable = append(data.Unavailable, "region suggestion")
		case found:
			data.Suggestion = &suggestion
		}
	}
	return data
}

