write_capacity.text:
func WriteCapacity(ctx context.Context, writer *globalcontrol.Writer, epoch uint64, c Capacity) error {
	if writer == nil {
		return errors.New("capacity requires the home writer")
	}
	for range 8 {
		prior, found, err := ReadCapacity(ctx, &writer.Reader)
		if err != nil {
			return err
		}
		if found {
			c.Spending, c.Reservations = prior.Spending, prior.Reservations
			c.BootstrapReservedCents = max(c.BootstrapReservedCents, prior.BootstrapReservedCents)
			if prior.BootstrapSHA256 != "" {
				c.BootstrapSHA256 = prior.BootstrapSHA256
			}
			if c.Spending != nil && c.State != StateNone {
				c.ProjectedCents = max(c.ProjectedCents, c.Spending.ProjectedCents)
				c.Ratio = float64(c.ProjectedCents) / float64(c.CapCents)
				if c.ProjectedCents >= c.CapCents {
					c.State = StateOver
				} else if c.State == StateOK && c.Ratio >= WarnRatio {
					c.State = StateWarn
				}
			}
		}
		payload, err := c.Encode()
		if err != nil {
			return err
		}
		var expected []byte
		if found {
			expected, err = prior.Encode()
			if err != nil {
				return err
			}
		}
		_, err = writer.PutDocument(ctx, epoch, globalcontrol.KindCapacity, protocol.GlobalScope, payload, func(stored []byte) error {
			if !sameCapacity(stored, expected) {
				return globalcontrol.ErrConflict
			}
			return nil
		})
		if errors.Is(err, globalcontrol.ErrConflict) {
			continue
		}
		return err
	}
	return globalcontrol.ErrConflict
}

global_read.text:
func (r *Reader) read(ctx context.Context, kind Kind, key string) (record, uint64, error) {
	if r == nil || r.stream == nil {
		return record{}, 0, errors.New("global control reader is not open")
	}
	readCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()
	message, err := r.stream.GetLastMsgForSubject(readCtx, subject(kind, key))
	if r.mirror && (err == nil || errors.Is(err, jetstream.ErrMsgNotFound)) {
		// Checked after the read: no gap up to the mirror's last sequence
		// now means no newer record for this subject was skipped before it.
		if gapErr := r.checkMirrorGapFree(readCtx); gapErr != nil {
			return record{}, 0, gapErr
		}
	}
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return record{}, 0, ErrNotFound
	}
	if err != nil {
		return record{}, 0, err
	}
	var stored record
	if err := protocol.DecodeStrict(message.Data, &stored, maxMessageBytes); err != nil ||
		stored.Version != recordVersion || stored.Kind != kind || stored.Key != key ||
		stored.Generation == 0 || stored.Epoch == 0 {
		return record{}, 0, ErrRecordCorrupt
	}
	if !epochHeaderMatches(message.Header, stored.Epoch) {
		return record{}, 0, ErrRecordCorrupt
	}
	return stored, message.Sequence, nil
}

global_write.text:
func (w *Writer) put(ctx context.Context, epoch uint64, kind Kind, key string, generation uint64, payload []byte,
	admit func(prior []byte) error,
) (uint64, error) {
	if epoch == 0 {
		return 0, authority.ErrFenced
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	if err := w.fencer.Guard(ctx, epoch); err != nil {
		return 0, err
	}
	for range maxAppendAttempts {
		lastSequence, err := w.establishTerm(ctx, epoch)
		if err != nil {
			return 0, err
		}
		next := max(generation, 1)
		prior, priorSequence, err := w.read(ctx, kind, key)
		switch {
		case errors.Is(err, ErrNotFound):
		case err != nil:
			return 0, err
		case priorSequence > lastSequence:
			continue
		case (generation == 0 || prior.Generation == generation) && bytes.Equal(prior.Payload, payload):
			// An identical retry after an unknown publish outcome is idempotent.
			return priorSequence, nil
		case generation == 0:
			next = prior.Generation + 1
		case generation <= prior.Generation:
			return 0, ErrStaleRecord
		}
		if epoch < prior.Epoch {
			return 0, authority.ErrFenced
		}
		if admit != nil {
			if err := admit(prior.Payload); err != nil {
				return 0, err
			}
		}
		data, err := protocol.EncodeJSON(record{
			Version: recordVersion, Kind: kind, Key: key, Generation: next, Epoch: epoch, Payload: payload,
		})
		if err != nil {
			return 0, err
		}
		if w.beforePublish != nil {
			w.beforePublish()
		}
		message := nats.NewMsg(subject(kind, key))
		message.Data = data
		message.Header.Set(EpochHeader, strconv.FormatUint(epoch, 10))
		publishCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		ack, err := w.js.PublishMsg(publishCtx, message,
			jetstream.WithExpectStream(StreamName),
			jetstream.WithExpectLastSequence(lastSequence),
			jetstream.WithExpectLastSequenceForSubject(priorSequence, subject(kind, key)),
			jetstream.WithMsgID(string(kind)+"."+key+"."+strconv.FormatUint(next, 10)),
		)
		cancel()
		if wrongLastSequence(err) {
			// Another append won: a newer term barrier or a concurrent write.
			// The next attempt observes it and fences or re-checks the CAS.
			continue
		}
		if err != nil {
			return 0, fmt.Errorf("publish global %s record: %w", kind, err)
		}
		if ack.Duplicate {
			// The message ID was seen; only an identical stored record is success.
			stored, sequence, readErr := w.read(ctx, kind, key)
			if readErr != nil || stored.Generation != next || !bytes.Equal(stored.Payload, payload) {
				return 0, ErrConflict
			}
			return sequence, nil
		}
		return ack.Sequence, nil
	}
	return 0, ErrConflict
}

suggest_load.text:
func (s *Store) Load(ctx context.Context) (State, uint64, error) {
	entry, err := s.kv.Get(ctx, stateKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return State{}, 0, nil
	}
	if err != nil {
		return State{}, 0, fmt.Errorf("read region suggestion state: %w", err)
	}
	var state State
	if err := protocol.DecodeStrict(entry.Value(), &state, maxStateBytes); err != nil {
		return State{}, 0, fmt.Errorf("decode region suggestion state: %w", err)
	}
	return state, entry.Revision(), nil
}

suggest_save.text:
func (s *Store) Save(ctx context.Context, epoch uint64, state State, revision uint64) (uint64, error) {
	if epoch == 0 {
		return 0, authority.ErrFenced
	}
	if err := s.fencer.Guard(ctx, epoch); err != nil {
		return 0, err
	}
	data, err := protocol.EncodeJSON(state)
	if err != nil {
		return 0, err
	}
	var written uint64
	if revision == 0 {
		written, err = s.kv.Create(ctx, stateKey, data)
	} else {
		written, err = s.kv.Update(ctx, stateKey, data, revision)
	}
	if errors.Is(err, jetstream.ErrKeyExists) || errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
		return 0, ErrStateChanged
	}
	if err != nil {
		return 0, fmt.Errorf("write region suggestion state: %w", err)
	}
	return written, nil
}

checkpoint.text:
func checkpointCapacityGrowth(compartment string, store nodescale.RecordStore, journal *oci.KVJournal) func(context.Context, nodescale.Recipe, core.UpdateInstancePoolRequest) (core.UpdateInstancePoolRequest, error) {
	return func(ctx context.Context, recipe nodescale.Recipe, request core.UpdateInstancePoolRequest) (core.UpdateInstancePoolRequest, error) {
		record, _, err := store.Load(ctx)
		if err != nil {
			return request, err
		}
		if record.Action == nil || record.Action.Kind != nodescale.Up || record.Recipe == nil || record.Reservation == nil ||
			record.Recipe.SHA256() != recipe.SHA256() || record.Reservation.OperationID != record.Action.ID ||
			record.Reservation.RecipeSHA256 != recipe.SHA256() || record.Reservation.CompartmentID != compartment ||
			!strings.EqualFold(record.Reservation.Cell, recipe.Cell) || request.InstancePoolId == nil || request.Size == nil ||
			record.TargetFrom == nil || *request.Size != *record.TargetFrom+1 {
			return request, fmt.Errorf("%w: exact durable action, receipt and target are required before OCI growth", nodescale.ErrCapacityPending)
		}
		receipt := record.Reservation
		prior, found, err := journal.GetCapacityRequest(ctx, record.Action.ID)
		if err != nil {
			return request, err
		}
		started := record.Action.Started.UTC()
		if found {
			if request.OpcRetryToken == nil || prior.RetryToken != *request.OpcRetryToken || !prior.StartedAt.Equal(started) {
				return request, fmt.Errorf("%w: original growth token or first-attempt identity changed", nodescale.ErrCapacityPending)
			}
			// An unknown outcome replays the original precondition and token, never a refreshed request.
			request.IfMatch, request.OpcRetryToken = new(prior.IfMatch), new(prior.RetryToken)
		}
		digest, err := capacityGrowthRequestSHA256(request)
		if err != nil {
			return request, err
		}
		checkpoint := oci.CapacityRequest{OperationID: record.Action.ID, RecipeSHA256: recipe.SHA256(),
			LogicalScopeSHA256: receipt.ScopeSHA256, ResolvedScopeSHA256: receipt.ResolvedScopeSHA256,
			BindingSHA256: receipt.BindingSHA256, GrantSHA256: receipt.GrantSHA256, GrantGeneration: receipt.GrantGeneration,
			TenancyID: receipt.TenancyID, Region: oci.Region(strings.ToUpper(recipe.Cell)), CompartmentID: compartment,
			PoolID: *request.InstancePoolId, RequestSHA256: digest, RetryToken: *request.OpcRetryToken, IfMatch: *request.IfMatch,
			Currency: receipt.Currency, ReservedMonthlyCents: receipt.MonthlyCents, QuoteSHA256: receipt.QuoteSHA256,
			TargetSize: uint32(*request.Size), StartedAt: started}
		if found && checkpoint != prior {
			return request, fmt.Errorf("%w: exact growth request differs from its original durable checkpoint", nodescale.ErrCapacityPending)
		}
		return request, journal.RecordCapacityRequest(ctx, checkpoint)
	}
}

